actor ControlledReadMarkerRepository:InboxReadMarkerRepository {
    private var pending:CheckedContinuation<InboxReadMarkerSource,Never>?,waiter:CheckedContinuation<Void,Never>?
    func source(_ c:InboxConversationFilesContext) async throws -> InboxReadMarkerSource {await withCheckedContinuation {pending=$0;waiter?.resume();waiter=nil}}
    func wait() async {if pending==nil {await withCheckedContinuation {waiter=$0}}}
    func resolve(_ source:InboxReadMarkerSource) {pending!.resume(returning:source);pending=nil}
}
